'@ | Set-Content -Encoding utf8 outputs/steps/01_inclusion.json; "'$orders = Import-Csv inputs/orders.csv; $rows = foreach ($o in $orders) { $why = if ($o.tenant -ne '"'alpha') {'TENANT'} elseif ("'$o.status -ne '"'paid') {'STATUS'} elseif ("'$o.posted_date -lt '"'2026-10-01' -or "'$o.posted_date -gt '"'2026-10-03') {'DATE'} else {'NONE'}; "'$included = $why -eq '"'NONE'; "'$discount = 0; $fee = 0; $net = 0; if ($included) { $discount = [int][Math]::Floor(([int]$o.gross_cents) / 10.0 + 0.5); if ($o.discount_code -eq '"'NONE') { "'$discount = 0 }; $fee = 200; $net = [int]$o.gross_cents - $discount - [int]$o.refund_cents + $fee }; [pscustomobject]@{order_id=$o.order_id;tenant=$o.tenant;status=$o.status;posted_date=$o.posted_date;gross_cents=$o.gross_cents;discount_code=$o.discount_code;refund_cents=$o.refund_cents;included=([string]$included).ToLower();discount_cents=$discount;fee_cents=$fee;net_cents=$net;exclusion_reason=$why} }; $rows | Export-Csv -NoTypeInformation -Encoding utf8 outputs/invoice_ledger.csv;'

